"""Local sparse biharmonic residual fit for C48 graph reconstruction. CPU only."""
import sys,json
from pathlib import Path
import numpy as np
from scipy import sparse
from scipy.sparse.linalg import spsolve
p=Path(sys.argv[1]);d=np.load(p);V=d['xy'];E=d['edges'];boundary=d['boundary'];values=d['boundary_values'];prior_idx=d['prior_indices'];prior_value=d['prior_values'];N=len(V);free=np.ones(N,bool);free[boundary]=False;fi=np.flatnonzero(free);mapping=np.full(N,-1,np.int32);mapping[fi]=np.arange(len(fi));w=1/np.maximum(np.sum((V[E[:,1]]-V[E[:,0]])**2,1),1e-14);degree=np.zeros(N);np.add.at(degree,E[:,0],w);np.add.at(degree,E[:,1],w);row=np.r_[np.arange(N),E[:,0],E[:,1]];col=np.r_[np.arange(N),E[:,1],E[:,0]];dat=np.r_[np.ones(N),-w/degree[E[:,0]],-w/degree[E[:,1]]];L=sparse.csr_matrix((dat,(row,col)),shape=(N,N));beta=.003;gamma=10.;P=sparse.csr_matrix((np.ones(len(prior_idx)),(np.arange(len(prior_idx)),mapping[prior_idx])),shape=(len(prior_idx),len(fi)));A=sparse.vstack([L[:,fi],sparse.eye(len(fi))*beta**.5,P*gamma**.5],format='csr');rhs=np.r_[-L[:,boundary]@values,np.zeros(len(fi)),prior_value*gamma**.5];normal=(A.T@A).tocsc();solution=spsolve(normal,A.T@rhs);corr=np.zeros(N);corr[boundary]=values;corr[fi]=solution;normalres=A.T@(A@solution-rhs);report={'solver':'SciPy sparse screened-biharmonic normal equations, local CPU','vertices':N,'free':len(fi),'boundary':len(boundary),'first_derivative_priors':len(prior_idx),'beta':beta,'gamma':gamma,'normal_equation_residual_max':float(np.abs(normalres).max()),'derivative_prior_height_residual_rms':float(np.sqrt(np.mean((corr[prior_idx]-prior_value)**2))),'derivative_prior_height_residual_max':float(np.abs(corr[prior_idx]-prior_value).max()),'maximum_correction':float(np.abs(corr).max())};np.savez_compressed(p.with_name('surface-solve-output.npz'),correction=corr);p.with_name('surface-solve-receipt.json').write_text(json.dumps(report,indent=2));print('RESULT '+json.dumps(report))
